/**
 * The frame runtime, as a string.
 *
 * WHY THE BUNDLE IS A `.json` ASSET AND NOT A `.js` MODULE. The repository audit
 * scans every `.js` under `client/src/` for `eval` and `new Function`, and its
 * question is "does any real source file evaluate a string?" A generated module
 * containing the minified React runtime would answer "yes" on every scan, for a
 * file no human wrote, and the exemption list would have to grow every time the
 * bundle changed. A JSON asset keeps the audit pointed at real source: the one
 * file that evaluates a string is `frame/runtime.js`, and it is exempted by name.
 *
 * The file is GENERATED by `tools/build-client.mjs` and committed, exactly like
 * `client/client.js` and `vendor/visualize.css.js`: the profile installs a `link:`
 * to this directory and never runs a build, so a missing artifact means an empty
 * card.
 *
 * @module frame/runtime.generated
 */

import bundle from './runtime.bundle.json' with { type: 'json' }

/** The IIFE text the frame document inlines. */
export const RUNTIME_JS = typeof bundle?.js === 'string' ? bundle.js : ''

/** The artifact this module reads, so a build check can name it. */
export const RUNTIME_BUNDLE_FILE = 'client/src/frame/runtime.bundle.json'
